import json
S = []
def n(scene, text, kick=None, **p): S.append({"scene": scene, "text": text, "spk": "n", "kick": kick, "params": p})
def j(scene, text, kick=None, **p): S.append({"scene": scene, "text": text, "spk": "j", "kick": kick, "params": p, "tight": True})
def t(scene, text, kick=None, **p): S.append({"scene": scene, "text": text, "spk": "t", "kick": kick, "params": p, "tight": True})
n("ship", "Three... two... one...", None, mode="count")
n("ship", "Did you see that explosion? Go on, turn the volume up.", None, mode="boom")
n("ship", "Still nothing?", None, mode="vol")
n("ship", "That robot just blew itself to pieces right outside Jack's spaceship. He saw the flash. He saw a piece of its head fly past the window. And he didn't hear a thing.", "SILENT EXPLOSION", mode="head")
n("ship", "But if Tilly floats past that same window and says,", None, mode="tilly")
t("ship", "Jack, did you break another robot?", None, mode="tilly", say="Jack, did you break another robot?")
n("ship", "he can hear her loud and clear over the radio.", None, mode="tilly", radio=True)
n("questions", "So how does a little radio get a message across space when a massive explosion can't get a single bang through? And what happens if a piece of that robot actually hits Jack's window?", "TWO BIG QUESTIONS")
n("table", "Let's start with something you can try at home. Tap a table with your finger.", "TRY IT AT HOME", mode="tap")
n("table", "That little knock starts with the tabletop vibrating. It pushes on the air beside it. Those air particles nudge their neighbours, and the disturbance travels through the air until it reaches your ear.", "HOW SOUND TRAVELS", mode="air")
n("stadium", "Picture a crowd doing a wave at a footy match. One person stands up, then the next, then the next. The wave goes all the way around the stadium, but everyone stays by their own seat.", "THE STADIUM WAVE", mode="wave")
n("airChain", "Sound works a bit like that. The vibration moves along as each bit of air pushes on the next.", "SOUND = A WAVE THROUGH AIR")
n("stadium", "Now imagine Jack is the only person in the stadium. He jumps up, throws both arms in the air, and looks around.", None, mode="alone")
n("stadium", "Absolutely nothing. He's going to be there a while.", "NO NEIGHBOURS, NO WAVE", mode="alone2")
n("bell", "So Tilly decides to try an experiment. She hangs a battery-powered bell inside a clear chamber. The bell rings, and you can see its little hammer going back and forth.", "THE BELL JAR EXPERIMENT", mode="ring")
n("bell", "Then Jack switches on a pump and starts pulling air out of the chamber. The ringing gets quieter. And quieter.", None, mode="pump")
n("bell", "Jack looks at Tilly.", None, mode="pumped")
j("bell", "Reckon the battery's dead?", None, mode="pumped", say="Reckon the battery's dead?", who="j")
t("bell", "Look at the hammer, Jack.", None, mode="pumped", say="Look at the hammer, Jack.", who="t")
n("bell", "It's still moving. The bell is still vibrating. But with much less air in the chamber, much less sound reaches us. Tilly lets the air back in, and the ringing gets louder again.", "STILL VIBRATING, LESS AIR", mode="back")
n("spaceGap", "Now think about that robot. The light from the explosion can travel across empty space, which is how Jack sees the flash. Sound needs matter to carry its vibrations. Between the robot and the ship, there's too little matter for Jack to hear that familiar movie-style boom.", "LIGHT YES, SOUND NO")
n("spacewalk", "So what about the radio? Imagine Jack and Tilly are both outside the ship. Jack waves and yells,", "WHAT ABOUT THE RADIO?", mode="yell")
j("spacewalk", "Tilly! Can you hear me?", None, mode="yell", say="Tilly! Can you hear me?", who="j")
n("spacewalk", "Jack hears himself because there's air inside his helmet. Tilly has air inside hers, too. But her helmet is a few metres away, and there's almost nothing in between to carry his voice.", "AIR IN HELMETS, NOTHING BETWEEN", mode="gap")
n("spacewalk", "Then Jack presses the radio button.", None, mode="radio")
j("spacewalk", "Tilly, can you hear me now?", None, mode="radio", say="Tilly, can you hear me now?", who="j")
t("spacewalk", "Yep. You can stop shouting.", None, mode="radio", say="Yep. You can stop shouting.", who="t")
n("chain3", "Here's what just happened. Jack's voice travelled through the air inside his helmet and reached a microphone. The microphone turned those vibrations into an electrical signal. The radio sent that message across space as radio waves, which can travel through a vacuum.", "SOUND TO RADIO WAVES", step=1)
n("chain3", "Tilly's radio picked up the signal. Her speaker vibrated, moved the air inside her helmet, and made sound she could hear.", "RADIO WAVES TO SOUND", step=2)
n("chain3", "So the trip had three parts. Sound from Jack's mouth to his microphone. Radio waves between the helmets. Then sound again from Tilly's speaker to her ears.", "THREE PARTS", step=3)
n("moon", "Now let's take the same idea to the Moon. Jack gives a rock a tap with a hammer. Tilly stands a few steps away. She doesn't hear a knock through the space between them, but something interesting is happening right under her boots.", "ON THE MOON", mode="tap")
n("moon", "The rock vibrates, and some of that vibration spreads through the ground.", "THROUGH THE GROUND", mode="ground")
n("tableEar", "Try this with the table from earlier. Put your ear against the tabletop and tap gently at the other end. Now lift your head and tap again. Hear the difference? When your ear is against the table, the vibrations have another way to reach you, through the solid wood.", "TRY IT: EAR ON THE TABLE")
n("moon", "On the Moon, Tilly places a sensitive vibration sensor on the ground. Jack taps the rock again. A little squiggle appears on her screen. She can turn that recording into audio and play it back through her helmet speaker.", "A VIBRATION SENSOR", mode="sensor")
n("moon", "And there it is. A little knock, picked up through the ground.", None, mode="sensor2")
n("ship", "Which brings us back to Jack's window. A piece of the robot is drifting straight towards it. This time, it hits the glass.", "BACK TO THE WINDOW", mode="impact")
n("ship", "Do you reckon Jack hears it?", None, mode="impact2")
n("ship", "Yes, if the impact makes the window vibrate enough. The glass can pass that vibration into the air inside the ship, and the air carries the sound to Jack's ears.", "GLASS, THEN AIR, THEN EARS", mode="inside")
n("splitView", "From outside, the shot is silent. From inside, Jack hears one little tap.", "OUTSIDE: SILENT. INSIDE: TAP.")
n("cta", "Now tell me in the comments which question you want us to explore next. What happens when you cry in space? Or how high could you jump on the Moon?", "WHAT SHOULD WE EXPLORE NEXT?")
n("cta", "And if you enjoy surprising facts and the science behind them, subscribe for more videos like this. See you in the next one!", None, mode="sub")
S.append({"scene": "endcard", "text": None, "kick": None, "params": {}, "dur": 6.0})
json.dump(S, open("segments.json", "w"), indent=1)
print(len(S), "segments,", sum(len(s["text"].split()) for s in S if s["text"]), "words")
